from __future__ import annotations

import re
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

from ..persistence.store import read_json, write_json
from .. import config


LICENSE_MARKERS = (
    "copyright",
    "licensed under",
    "spdx-license-identifier",
    "apache license",
    "mit license",
    "gnu general public",
    "all rights reserved",
    "redistribution and use in source and binary forms",
)

GENERATED_MARKERS = (
    "generated by",
    "do not edit",
    "autogenerated",
    "auto-generated",
    "@generated",
    "this file was generated",
    "generated on",
)

TOOLING_MARKERS = (
    "checkstyle",
    "spotless",
    "eslint",
    "prettier-ignore",
    "prettier-ignore-start",
    "prettier-ignore-end",
    "noinspection",
    "nosonar",
    "non-nls",
    "fmt: off",
    "fmt: on",
    "gofmt",
    "istanbul ignore",
    "c8 ignore",
    "v8 ignore",
    "ruff:",
    "mypy:",
    "pyright:",
    "type: ignore",
    "nosec",
    "golangci",
    "ktlint",
    "swaggertype",
    "checkstyle off",
    "noqa",
)

TOOLING_DIRECTIVE_PATTERN = re.compile(
    r"checkstyle\s*:\s*(?:off|on)\b"
    r"|checkstyle\s+(?:off|on)\b"
    r"|spotless\s*:\s*(?:off|on)\b"
    r"|eslint-disable"
    r"|prettier-ignore"
    r"|\bnoinspection\b"
    r"|\bnosonar\b"
    r"|\$NON-NLS"
    r"|\bfmt\s*:\s*(?:off|on)\b"
    r"|\bgofmt\b"
    r"|istanbul\s+ignore\b"
    r"|\bc8\s+ignore\b"
    r"|\bv8\s+ignore\b"
    r"|\bruff\s*:"
    r"|\bmypy\s*:"
    r"|\bpyright\s*:"
    r"|type\s*:\s*ignore\b"
    r"|\bnosec\b"
    r"|\bgolangci\b"
    r"|\bktlint\b"
    r"|\bnoqa\b"
    r"|\bnoqa:[A-Z0-9,\s]+\b",
    re.IGNORECASE,
)

SOURCEMAP_MARKERS = ("sourceurl", "sourcemappingurl", "source-map")


@dataclass
class PolicyDecision:
    prohibited: bool
    category: str
    reason: str


@dataclass
class Policy:
    license_header_line_budget: int = 25
    license_markers: tuple[str, ...] = LICENSE_MARKERS
    generated_markers: tuple[str, ...] = GENERATED_MARKERS
    tooling_markers: tuple[str, ...] = TOOLING_MARKERS
    sourcemap_markers: tuple[str, ...] = SOURCEMAP_MARKERS
    exempt_paths: tuple[str, ...] = field(default_factory=tuple)
    exempt_suffixes: tuple[str, ...] = field(default_factory=tuple)
    generated_path_markers: tuple[str, ...] = ("/target/", "/node_modules/", "/.git/", "/generated-sources/")

    @staticmethod
    def load(path: Path | None = None) -> "Policy":
        document = read_json(path or config.comment_policy_path(), {}) or {}
        return Policy(
            license_header_line_budget=int(document.get("license_header_line_budget", 25)),
            license_markers=tuple(document.get("license_markers", LICENSE_MARKERS)),
            generated_markers=tuple(document.get("generated_markers", GENERATED_MARKERS)),
            tooling_markers=tuple(document.get("tooling_markers", TOOLING_MARKERS)),
            sourcemap_markers=tuple(document.get("sourcemap_markers", SOURCEMAP_MARKERS)),
            exempt_paths=tuple(document.get("exempt_paths", ())),
            exempt_suffixes=tuple(document.get("exempt_suffixes", ())),
            generated_path_markers=tuple(document.get("generated_path_markers", ("/target/", "/node_modules/", "/.git/", "/generated-sources/"))),
        )

    def to_document(self) -> dict[str, Any]:
        return {
            "license_header_line_budget": self.license_header_line_budget,
            "license_markers": list(self.license_markers),
            "generated_markers": list(self.generated_markers),
            "tooling_markers": list(self.tooling_markers),
            "sourcemap_markers": list(self.sourcemap_markers),
            "exempt_paths": list(self.exempt_paths),
            "exempt_suffixes": list(self.exempt_suffixes),
            "generated_path_markers": list(self.generated_path_markers),
        }

    def save(self, path: Path | None = None) -> Path:
        return write_json(path or config.comment_policy_path(), self.to_document())


def classify_comment(comment_text: str, starting_line: int, policy: Policy) -> PolicyDecision:
    lowered = comment_text.lower()
    stripped = comment_text.strip()

    if any(marker in lowered for marker in policy.sourcemap_markers):
        return PolicyDecision(False, "SOURCEMAP_DIRECTIVE", "source-map directive preserved")
    if any(marker in lowered for marker in policy.generated_markers):
        return PolicyDecision(False, "GENERATED_MARKER", "generated-file marker preserved")
    if any(marker in lowered for marker in policy.license_markers) and starting_line <= policy.license_header_line_budget:
        return PolicyDecision(False, "LICENSE_HEADER", "mandatory copyright or license notice preserved")
    if any(marker in lowered for marker in policy.license_markers):
        return PolicyDecision(False, "LICENSE_HEADER", "license notice preserved outside header budget")
    if any(marker in lowered for marker in policy.tooling_markers) and TOOLING_DIRECTIVE_PATTERN.search(comment_text):
        return PolicyDecision(False, "TOOLING_DIRECTIVE", "tool or linter directive preserved")
    if stripped.startswith("#!") or stripped.startswith("#!"):
        return PolicyDecision(False, "SHEBANG", "interpreter directive preserved")
    if re.fullmatch(r"//\s*region.*|//\s*endregion.*", stripped):
        return PolicyDecision(True, "FOLDING_MARKER", "IDE folding marker carries no semantics")
    if re.search(r"\b(todo|fixme|xxx|hack)\b", lowered):
        return PolicyDecision(True, "TODO_MARKER", "todo or fixme marker")
    return PolicyDecision(True, "ORDINARY_COMMENT", "ordinary explanatory comment")


def is_exempt_path(relative_path: str, policy: Policy) -> bool:
    normalized = "/" + relative_path.replace("\\", "/")
    if any(marker in normalized for marker in policy.generated_path_markers):
        return True
    for exempt in policy.exempt_paths:
        if normalized == exempt or normalized.endswith(exempt):
            return True
    for suffix in policy.exempt_suffixes:
        if normalized.endswith(suffix):
            return True
    return False
